using System;
using System.Collections.Generic;
using AwesomeAssertions;
using Xunit;

namespace ViciOne.Suite.DataPort;

public class PostgreSqlCommands_ComposeCreateTableCommandText
{
    [Fact]
    public void Acceptance()
    {
        Table table = new("users",
        [
            new("id", "int", true, true, true),
            new("name", "text", false, false, false),
        ]);

        Schema schema = new("dbo", [table,]);

        PostgreSqlCommands.ComposeCreateTableCommandText(schema, table).Should().Be("""
        CREATE TABLE "dbo"."users" (
        "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
        "name" text);
        """.ReplaceLineEndings());
    }
}

public class PostgreSqlCommands_ComposeCopyCommand
{
    [Fact]
    public void Acceptance()
    {
        var table = "users";
        var schema = "test";

        var columnInfos = new List<ColumnInfo>()
        {
            new(new TableInfo("default", schema, table), "id", true, false, typeof(Guid))
        };

        PostgreSqlCommands.ComposeCopyCommand(table, schema, columnInfos).Should().Be("""
        COPY "test"."users" ("id") FROM STDIN (FORMAT BINARY);
        """.ReplaceLineEndings());
    }
}

public class PostgreSqlCommands_ComposeCreateStructureCommandText
{
    [Fact]
    public void Acceptance()
    {
        Table table = new("table_name1",
        [
            new("id", "int", false, false, false),
            new("name", "text", false, false, false),
        ]);

        Table table2 = new("table_name1",
        [
            new("id", "double precision", false, false, false),
            new("name", "text", false, false, false),
        ]);

        Schema schema = new("test1", [table,]);
        Schema schema2 = new("test2", [table2,]);
        Schema schema3 = new("test3", [table,]);

        var missingSchemasSchemas = new List<Schema>() { schema, schema2 };
        var missingTablesSchemas = new List<Schema>() { schema, schema2, schema3 };
        var missingSchemas = new List<Database>() { new(string.Empty, missingSchemasSchemas) };
        var missingTables = new List<Database>() { new(string.Empty, missingTablesSchemas), };

        PostgreSqlCommands.ComposeCreateStructureCommandText(missingSchemas, missingTables).Should().Be("""
        CREATE SCHEMA "test1";
        CREATE SCHEMA "test2";
        CREATE TABLE "test1"."table_name1" (
        "id" int,
        "name" text);
        CREATE TABLE "test2"."table_name1" (
        "id" double precision,
        "name" text);
        CREATE TABLE "test3"."table_name1" (
        "id" int,
        "name" text);
        """.ReplaceLineEndings());
    }
}
